static int
eval4(char_u **arg, typval_T *rettv, evalarg_T *evalarg)
{
    typval_T	var2;
    char_u	*p;
    int		i;
    exptype_T	type = EXPR_UNKNOWN;
    int		len = 2;
    int		ic;
    if (eval5(arg, rettv, evalarg) == FAIL)
	return FAIL;
    p = *arg;
    switch (p[0])
    {
	case '=':   if (p[1] == '=')
			type = EXPR_EQUAL;
		    else if (p[1] == '~')
			type = EXPR_MATCH;
		    break;
	case '!':   if (p[1] == '=')
			type = EXPR_NEQUAL;
		    else if (p[1] == '~')
			type = EXPR_NOMATCH;
		    break;
	case '>':   if (p[1] != '=')
		    {
			type = EXPR_GREATER;
			len = 1;
		    }
		    else
			type = EXPR_GEQUAL;
		    break;
	case '<':   if (p[1] != '=')
		    {
			type = EXPR_SMALLER;
			len = 1;
		    }
		    else
			type = EXPR_SEQUAL;
		    break;
	case 'i':   if (p[1] == 's')
		    {
			if (p[2] == 'n' && p[3] == 'o' && p[4] == 't')
			    len = 5;
			i = p[len];
			if (!isalnum(i) && i != '_')
			    type = len == 2 ? EXPR_IS : EXPR_ISNOT;
		    }
		    break;
    }
    if (type != EXPR_UNKNOWN)
    {
	if (p[len] == '?')
	{
	    ic = TRUE;
	    ++len;
	}
	else if (p[len] == '#')
	{
	    ic = FALSE;
	    ++len;
	}
	else
	    ic = p_ic;
	*arg = skipwhite(p + len);
	if (eval5(arg, &var2, evalarg) == FAIL)
	{
	    clear_tv(rettv);
	    return FAIL;
	}
	if (evalarg != NULL && (evalarg->eval_flags & EVAL_EVALUATE))
	{
	    int ret = typval_compare(rettv, &var2, type, ic);
	    clear_tv(&var2);
	    return ret;
	}
    }
    return OK;
}

