  char_u *p;
  char_u *name;
  funcdict_T fudi;
  p = (char_u *)eap->arg;
  name = trans_function_name((char **)&p, eap->skip, 0, &fudi, NULL);
  xfree(fudi.fd_newkey);
  if (name == NULL) {
    if (fudi.fd_dict != NULL && !eap->skip) {
      emsg(_(e_funcref));
    }
    return;
  }
  if (!ends_excmd(*skipwhite((char *)p))) {
    xfree(name);
    semsg(_(e_trailing_arg), p);
    return;
