  eap->nextcmd = check_nextcmd((char *)p);
  if (eap->nextcmd != NULL) {
    *p = NUL;
  }
  if (!eap->skip) {
    fp = find_func(name);
  }
  xfree(name);
  if (!eap->skip) {
    if (fp == NULL) {
      if (!eap->forceit) {
        semsg(_(e_nofunc), eap->arg);
      }
      return;
    }
    if (fp->uf_calls > 0) {
      semsg(_("E131: Cannot delete function %s: It is in use"), eap->arg);
      return;
    }
    if (fp->uf_refcount > 2) {
      semsg(_("Cannot delete function %s: It is being used internally"),
            eap->arg);
      return;
    }
    if (fudi.fd_dict != NULL) {
      tv_dict_item_remove(fudi.fd_dict, fudi.fd_di);
