    int j = hisidx[type];
    if (j >= 0) {
      int l1 = MIN(j + 1, newlen);             
      int l2 = MIN(newlen, oldlen) - l1;       
      int i1 = j + 1 - l1;                     
      int i2 = MAX(l1, oldlen - newlen + l1);  
      if (newlen) {
        memcpy(&temp[0], &history[type][i2], (size_t)l2 * sizeof(*temp));
