{
    colnr_T	scol = 0, ccol = 0, ecol = 0;
    int		row = 0;
    int		rowoff = 0;
    colnr_T	coloff = 0;
    if (pos->lnum >= wp->w_topline && pos->lnum < wp->w_botline)
