    }
    if (has_mbyte && !IS_SPECIAL(c) && MB_BYTE2LEN(c) > 1)
    {
	char_u	*p;
	*sp = str;
	p = mb_unescape(sp);
	if (p != NULL)
	    c = (*mb_ptr2char)(p);
	else
	    *sp = str + 1;
